This validator uses lower-left coordinates and reports all errors it finds. Pass `allow_rotation=True` to permit 8 × 12 rectangles as well as 12 × 8.

```python
from itertools import combinations
from math import isfinite


def validate_rectangles(rectangles, *, allow_rotation=False):
    """Validate mappings with id, x, y, width and height; return error strings."""
    errors = []
    valid = []
    orientations = {(12, 8)}
    if allow_rotation:
        orientations.add((8, 12))

    for index, rect in enumerate(rectangles):
        label = rect.get("id", f"rectangle {index + 1}")
        try:
            x, y, w, h = (rect[k] for k in ("x", "y", "width", "height"))
        except KeyError as exc:
            errors.append(f"{label}: missing {exc.args[0]}")
            continue

        if not all(isinstance(v, (int, float)) and not isinstance(v, bool)
                   and isfinite(v) for v in (x, y, w, h)):
            errors.append(f"{label}: coordinates and dimensions must be finite numbers")
            continue
        if w <= 0 or h <= 0:
            errors.append(f"{label}: dimensions must be positive")
            continue
        if (w, h) not in orientations:
            errors.append(f"{label}: orientation or dimensions {w} × {h} not permitted")
        if not (1 <= x and x + w <= 41 and 1 <= y and y + h <= 29):
            errors.append(f"{label}: outside usable area")
        valid.append((label, x, y, w, h))

    for a, b in combinations(valid, 2):
        la, xa, ya, wa, ha = a
        lb, xb, yb, wb, hb = b
        if xa < xb + wb and xb < xa + wa and ya < yb + hb and yb < ya + ha:
            errors.append(f"{la} and {lb}: positive-area overlap")
    return errors
```

An empty list means validation passed. Strict overlap comparisons allow edges and corners to touch.

These `unittest` cases assume the earlier `validate_rectangles` function is in scope. Each case isolates one condition.

```python
import unittest


class TestValidateRectangles(unittest.TestCase):
    def test_positive_area_overlap(self):
        rectangles = [
            {"id": "A", "x": 1, "y": 1, "width": 12, "height": 8},
            {"id": "B", "x": 12, "y": 1, "width": 12, "height": 8},
        ]
        self.assertEqual(validate_rectangles(rectangles),
                         ["A and B: positive-area overlap"])

    def test_shared_edge_is_allowed(self):
        rectangles = [
            {"id": "A", "x": 1, "y": 1, "width": 12, "height": 8},
            {"id": "D", "x": 1, "y": 9, "width": 12, "height": 8},
        ]
        self.assertEqual(validate_rectangles(rectangles), [])

    def test_out_of_bounds(self):
        rectangles = [
            {"id": "A", "x": 0, "y": 1, "width": 12, "height": 8},
        ]
        self.assertEqual(validate_rectangles(rectangles),
                         ["A: outside usable area"])

    def test_rotation_disabled(self):
        rectangles = [
            {"id": "R", "x": 1, "y": 1, "width": 8, "height": 12},
        ]
        self.assertEqual(validate_rectangles(rectangles),
                         ["R: orientation or dimensions 8 × 12 not permitted"])


if __name__ == "__main__":
    unittest.main()
```

Expected result: all four tests pass. The first, third, and fourth confirm the specified error messages; the edge-contact case expects no errors.
